package ledger;

import java.io.FileDescriptor;
import java.io.FileOutputStream;
import java.io.PrintStream;
import java.nio.charset.StandardCharsets;

/** エントリポイント。出力は成功時のみ標準出力へ、失敗時は stderr に 1 行。 */
public final class Main {
    private Main() {
    }

    public static void main(String[] args) {
        PrintStream out = new PrintStream(new FileOutputStream(FileDescriptor.out), false, StandardCharsets.UTF_8);
        PrintStream err = new PrintStream(new FileOutputStream(FileDescriptor.err), false, StandardCharsets.UTF_8);
        int code = run(args, System.getProperty("user.home") + "/.ledger.csv", out, err);
        out.flush();
        err.flush();
        System.exit(code);
    }

    /** テストしやすいよう、ストリームと既定パスを受け取って終了コードを返す。 */
    static int run(String[] args, String defaultDataPath, PrintStream out, PrintStream err) {
        try {
            // 引数検証 → ファイル処理の順
            CommandLine cl = CommandLine.parse(args, defaultDataPath);
            String result = cl.command().execute(new LedgerRepository(cl.dataPath()));
            out.write(result.getBytes(StandardCharsets.UTF_8), 0, result.getBytes(StandardCharsets.UTF_8).length);
            return 0;
        } catch (LedgerException e) {
            err.write(("error: " + e.getMessage() + "\n").getBytes(StandardCharsets.UTF_8), 0,
                    ("error: " + e.getMessage() + "\n").getBytes(StandardCharsets.UTF_8).length);
            return e.exitCode();
        } catch (RuntimeException e) {
            String msg = "error: unexpected failure: " + String.valueOf(e.getMessage()).replace('\n', ' ') + "\n";
            err.write(msg.getBytes(StandardCharsets.UTF_8), 0, msg.getBytes(StandardCharsets.UTF_8).length);
            return LedgerException.EXIT_IO;
        }
    }
}
